import{c as l,Q as a,j as o,m as s}from"./chunks/framework.DOi4mjdC.js";const e="/assets/MX%E6%A0%BC%E5%BC%8F%E7%BB%84%E6%88%90%E7%A4%BA%E6%84%8F%E5%9B%BE.COzfIjfr.png",p="/assets/MxMatmul%E7%9F%A9%E9%98%B5%E4%B9%98%E7%A4%BA%E6%84%8F%E5%9B%BE.P8JJJGza.png",n="/assets/A%E7%9F%A9%E9%98%B5%E5%9C%A8%E4%B8%8D%E5%90%8C%E4%BD%8D%E7%BD%AE%E7%9A%84%E6%8E%92%E5%B8%83%E6%A0%BC%E5%BC%8F.BIObJkvp.png",i="/assets/B%E7%9F%A9%E9%98%B5%E5%9C%A8%E4%B8%8D%E5%90%8C%E4%BD%8D%E7%BD%AE%E7%9A%84%E6%8E%92%E5%B8%83%E6%A0%BC%E5%BC%8F.DHgi5hJ9.png",g="/assets/scaleA%E7%9F%A9%E9%98%B5%E5%9C%A8%E4%B8%8D%E5%90%8C%E4%BD%8D%E7%BD%AE%E7%9A%84%E6%8E%92%E5%B8%83%E6%A0%BC%E5%BC%8F.BVgVoKpB.png",u="/assets/scaleB%E7%9F%A9%E9%98%B5%E5%9C%A8%E4%B8%8D%E5%90%8C%E4%BD%8D%E7%BD%AE%E7%9A%84%E6%8E%92%E5%B8%83%E6%A0%BC%E5%BC%8F.DkJ3Wcsq.png",T=JSON.parse('{"title":"MxMatmul场景","description":"","frontmatter":{},"headers":[{"level":1,"title":"MxMatmul场景","slug":"mxmatmul场景"},{"level":2,"title":"背景介绍","slug":"背景介绍"},{"level":2,"title":"功能介绍","slug":"功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景"},{"level":2,"title":"实现流程","slug":"实现流程"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/MxMatmul场景.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/MxMatmul场景.md"}'),c={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/MxMatmul场景.md"};function r(d,t,q,h,m,b){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="mxmatmul场景" tabindex="-1">MxMatmul场景 <a class="header-anchor" href="#mxmatmul场景" aria-label="Permalink to &quot;MxMatmul场景&quot;">​</a></h1><h2 id="背景介绍" tabindex="-1">背景介绍 <a class="header-anchor" href="#背景介绍" aria-label="Permalink to &quot;背景介绍&quot;">​</a></h2><p>浮点数在科学计算、图像处理、神经网络等领域应用广泛。以AI训练为例，现有的浮点数格式或数值范围不足，或精度不高，这影响了模型的收敛速度和性能。如果要同时满足数值范围和精度的要求，将会导致内存占用过大，从而增加数据存储和传输的成本。基于此种情况，业内提出了一种新的浮点数格式——微缩放（Microscaling，MX）格式。MX格式的浮点数可以支持更低比特位宽的AI训练和推理，并且占用的内存更少。符合MX标准的数据格式在使用8位或更低比特位的情况下，能够实现稳健的AI训练和推理模型精度。</p><p>MX格式是一种块数据格式，若干个数据可以组成一个块（或者一个组），数据以块为单位。MX格式的数据由三部分构成：</p><ul><li>共享缩放因子X，位宽为w bits；</li><li>私有元素P&lt;sub&gt;i&lt;/sub&gt;，位宽为d bits；</li><li>块大小k，表示多少个低比特数据形成一个块；</li></ul><p>所有k个元素P&lt;sub&gt;i&lt;/sub&gt;有相同的位宽和数据类型，并且共享一个缩放因子X，每个包含k个元素的块可以使用（w+k*d）位进行编码。元素的数据类型和缩放因子可以独立选择。</p><p>下图为MX格式的浮点数的数据结构，S、E和M分别用于表示浮点数的符号、指数和尾数字段的值。其中，共享缩放因子X是一个用于整个数据块的缩放比例因子，它决定了数据块中所有元素的动态范围。通过引入共享缩放因子，MX格式的数据能够在保持低位宽的同时，灵活地表示不同范围的数据。块大小k指的是组成一个数据块（或组）的低比特数据的数量。私有元素P&lt;sub&gt;i&lt;/sub&gt;是指数据块中的每个低比特数据元素。这些元素经过缩放因子X的调整后，共同表示了一个高精度的浮点数或整数。</p><p><strong>图 1</strong> MX格式组成示意图<br><img src="'+e+'" alt="" title="MX格式组成示意图"></p><p>MX格式的数据类型包含多种，例如MXFP8、MXFP4、MXFP16、MXINT4等。下表列举了<a href="#zh-cn_topic_0000002270097206_section310824820358">MxMatmul场景</a>（全称Microscaling Matmul）支持的数据类型。</p><p><strong>表 1</strong> MxMatmul支持MX格式的数据类型</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;数据类型&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;私有元素数据类型&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;私有元素位宽（d）&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;块大小(k)&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;共享缩放因子数据类型&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;共享缩放因子位宽(w)&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;MXFP8&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;fp8_e5m2_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;8&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;32&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;fp8_e8m0_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;8&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;MXFP8&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;fp8_e4m3fn_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;8&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;32&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;fp8_e8m0_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;8&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;MXFP4&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;fp4x2_e1m2_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;4&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;32&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;fp8_e8m0_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;8&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;MXFP4&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;fp4x2_e2m1_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;4&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;32&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;fp8_e8m0_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;16.666666666666664%&quot;&gt;&lt;p&gt;8&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><p>MxMatmul（全称Microscaling Matmul）为带有量化系数的矩阵乘法，即左矩阵和右矩阵均有对应的量化系数矩阵，左量化系数矩阵scaleA和右量化系数矩阵scaleB。MxMatmul场景中，左量化系数矩阵与左矩阵乘积，右量化系数矩阵与右矩阵乘积，对两个乘积的结果做矩阵乘法。</p><p>MxMatmul的计算公式为：C = (scaleA ⊗ A) * (scaleB ⊗ B) + Bias，“⊗”表示广播乘法，左/右矩阵与左/右量化系数矩阵做乘积时，K方向上每32个元素共享一个量化因子，如<a href="#zh-cn_topic_0000002270097206_fig1942919398330">图2</a>所示。</p><ul><li>A、scaleA、B、scaleB为源操作数。A为左矩阵，形状为[M, K]；scaleA为左量化系数矩阵，形状为[M, K/32]；B为右矩阵，形状为[K, N]；scaleB为右量化系数矩阵，形状为[K/32, N]。</li><li>C为目的操作数，存放矩阵乘结果的矩阵，形状为[M, N]。</li><li>Bias为矩阵乘偏置，形状为[1, N]。对(scaleA ⊗ A) * (scaleB ⊗ B)结果矩阵的每一行都采用该Bias进行偏置。</li></ul><p><strong>图 2</strong> MxMatmul矩阵乘示意图<br><img src="'+p+'" alt="" title="MxMatmul矩阵乘示意图"></p><p>矩阵A、scaleA、B、scaleB在不同位置中的排布格式分别如下图所示。</p><p><strong>图 3</strong> A矩阵在不同位置的排布格式<br><img src="'+n+'" alt="" title="A矩阵在不同位置的排布格式"></p><p><strong>图 4</strong> B矩阵在不同位置的排布格式<br><img src="'+i+'" alt="" title="B矩阵在不同位置的排布格式"></p><p><strong>图 5</strong> scaleA矩阵在不同位置的排布格式<br><img src="'+g+'" alt="" title="scaleA矩阵在不同位置的排布格式"></p><p><strong>图 6</strong> scaleB矩阵在不同位置的排布格式<br><img src="'+u+`" alt="" title="scaleB矩阵在不同位置的排布格式"></p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><p>矩阵计算之前，需要对A、B矩阵进行量化操作的场景。当前该场景下，Matmul输入输出矩阵支持的数据类型如下表所示。</p><p><strong>表 2</strong> MxMatmul支持的量化场景</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.41%&quot;&gt;&lt;p&gt;A矩阵&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;20.599999999999998%&quot;&gt;&lt;p&gt;B矩阵&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;15.340000000000002%&quot;&gt;&lt;p&gt;ScaleA矩阵/ScaleB矩阵&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.85%&quot;&gt;&lt;p&gt;Bias矩阵&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.72%&quot;&gt;&lt;p&gt;C矩阵&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.080000000000002%&quot;&gt;&lt;p&gt;支持平台&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.41%&quot;&gt;&lt;p&gt;fp4x2_e1m2_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;20.599999999999998%&quot;&gt;&lt;p&gt;fp4x2_e1m2_t/fp4x2_e2m1_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;15.340000000000002%&quot;&gt;&lt;p&gt;fp8_e8m0_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.85%&quot;&gt;&lt;p&gt;float/half/bfloat16_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.72%&quot;&gt;&lt;p&gt;float/half/bfloat16_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.080000000000002%&quot;&gt;&lt;p&gt;&lt;span&gt;Ascend 950PR/Ascend 950DT&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.41%&quot;&gt;&lt;p&gt;fp4x2_e2m1_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;20.599999999999998%&quot;&gt;&lt;p&gt;fp4x2_e2m1_t/fp4x2_e1m2_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;15.340000000000002%&quot;&gt;&lt;p&gt;fp8_e8m0_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.85%&quot;&gt;&lt;p&gt;float/half/bfloat16_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.72%&quot;&gt;&lt;p&gt;float/half/bfloat16_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.080000000000002%&quot;&gt;&lt;p&gt;&lt;span&gt;Ascend 950PR/Ascend 950DT&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.41%&quot;&gt;&lt;p&gt;fp8_e4m3fn_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;20.599999999999998%&quot;&gt;&lt;p&gt;fp8_e4m3fn_t/fp8_e5m2_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;15.340000000000002%&quot;&gt;&lt;p&gt;fp8_e8m0_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.85%&quot;&gt;&lt;p&gt;float/half/bfloat16_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.72%&quot;&gt;&lt;p&gt;float/half/bfloat16_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.080000000000002%&quot;&gt;&lt;p&gt;&lt;span&gt;Ascend 950PR/Ascend 950DT&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;10.41%&quot;&gt;&lt;p&gt;fp8_e5m2_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;20.599999999999998%&quot;&gt;&lt;p&gt;fp8_e4m3fn_t/fp8_e5m2_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;15.340000000000002%&quot;&gt;&lt;p&gt;fp8_e8m0_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.85%&quot;&gt;&lt;p&gt;float/half/bfloat16_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.72%&quot;&gt;&lt;p&gt;float/half/bfloat16_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.080000000000002%&quot;&gt;&lt;p&gt;&lt;span&gt;Ascend 950PR/Ascend 950DT&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><h2 id="实现流程" tabindex="-1">实现流程 <a class="header-anchor" href="#实现流程" aria-label="Permalink to &quot;实现流程&quot;">​</a></h2><p>Host侧自动获取Tiling参数的关键步骤介绍如下：</p><ol><li><p><strong>创建Tiling对象</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>matmul_tiling::MatmulApiTiling cubeTiling(ascendcPlatform);</span></span></code></pre></div><p>传入硬件平台信息创建PlatformAscendC对象，然后创建Tiling对象，硬件平台信息可以通过GetPlatformInfo获取。</p></li><li><p><strong>设置A、B、C、Bias的内存逻辑位置、格式、数据类型以及是否转置的信息，设置scaleA、scaleB的内存逻辑位置、格式以及是否转置的信息。</strong></p><p>调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetScaleAType.md" target="_blank" rel="noreferrer">SetScaleAType</a>、<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetScaleBType.md" target="_blank" rel="noreferrer">SetScaleBType</a>接口，设置scaleA、scaleB的内存逻辑位置、格式以及是否转置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cubeTiling.SetAType(AscendC::TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT8_E5M2, false);</span></span>
<span class="line"><span>cubeTiling.SetBType(AscendC::TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT8_E5M2, true);</span></span>
<span class="line"><span>cubeTiling.SetScaleAType(AscendC::TPosition::GM, CubeFormat::ND, false);</span></span>
<span class="line"><span>cubeTiling.SetScaleBType(AscendC::TPosition::GM, CubeFormat::ND, true);</span></span>
<span class="line"><span>cubeTiling.SetCType(AscendC::TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);</span></span>
<span class="line"><span>cubeTiling.SetBiasType(AscendC::TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);</span></span></code></pre></div></li><li><p><strong>使能MxMatmul场景</strong>。</p><p>调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetMadType.md" target="_blank" rel="noreferrer">SetMadType</a>接口，设置Tiling计算逻辑为MxMatmul场景。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cubetiling.SetMadType(MatrixMadType::MXMODE);</span></span></code></pre></div></li><li><p><strong>设置矩阵shape信息。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cubeTiling.SetShape(M, N, K);</span></span>
<span class="line"><span>cubeTiling.SetOrgShape(M, N, K); // 设置原始完整的形状M、N、K</span></span></code></pre></div></li><li><p><strong>设置可用空间大小信息。</strong></p><p>设置Matmul计算时可用的L1 Buffer/L0C Buffer/Unified Buffer空间大小，-1表示AI处理器对应Buffer的大小。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cubeTiling.SetBufferSpace(-1, -1, -1);</span></span></code></pre></div></li><li><p><strong>按需设置其他参数，比如设置bias参与计算。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cubeTiling.EnableBias(true);</span></span></code></pre></div></li><li><p><strong>获取Tiling参数。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MatmulCustomTilingData tiling;</span></span>
<span class="line"><span>if (cubeTiling.GetTiling(tiling.cubeTilingData) == -1){ </span></span>
<span class="line"><span>    return ge::GRAPH_FAILED;  </span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>Tiling参数的序列化保存等其他操作。</p></li></ol><p>Kernel侧的关键步骤介绍如下：</p><ol><li><p><strong>创建Matmul对象。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// MxMatmul场景通过MatmulTypeWithScale定义A、scaleA、B、scaleB的参数类型信息</span></span>
<span class="line"><span>typedef AscendC::MatmulTypeWithScale&lt;AscendC::TPosition::GM, AscendC::TPosition::GM, CubeFormat::ND, fp8_e5m2_t, isTransposeA&gt; aType; </span></span>
<span class="line"><span>typedef AscendC::MatmulTypeWithScale&lt;AscendC::TPosition::GM, AscendC::TPosition::GM, CubeFormat::ND, fp8_e5m2_t, isTransposeB&gt; bType;</span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; cType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; biasType; </span></span>
<span class="line"><span>// 定义matmul对象时，传入MatmulWithScalePolicy表明使能MxMatmul模板策略</span></span>
<span class="line"><span>AscendC::Matmul&lt;aType, bType, cType, biasType, CFG_MDL, MatmulCallBackFunc&lt;nullptr, nullptr, nullptr&gt;, AscendC::Impl::Detail::MatmulWithScalePolicy&gt; mm;</span></span></code></pre></div><p>创建对象时需要传入A、scaleA、B、scaleB、C、Bias的参数类型信息， A、scaleA、B、scaleB类型信息通过<a href="#zh-cn_topic_0000002270097206_table14759942142014">MatmulTypeWithScale</a>来定义，C、Bias类型信息通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Matmul%E4%BD%BF%E7%94%A8%E8%AF%B4%E6%98%8E.md" target="_blank" rel="noreferrer">MatmulType</a>来定义，包括：内存逻辑位置、数据格式、数据类型、转置信息。同时，通过模板参数<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulPolicy.md" target="_blank" rel="noreferrer">MatmulPolicy</a>传入<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulPolicy.md" target="_blank" rel="noreferrer">MatmulWithScalePolicy</a>表明使能MxMatmul场景。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;TPosition POSITION, TPosition SCALE_POSITION, CubeFormat FORMAT, typename TYPE, bool ISTRANS = false, TPosition SRCPOS = TPosition::GM, CubeFormat SCALE_FORMAT = FORMAT, bool SCALE_ISTRANS = ISTRANS, TPosition SCALE_SRCPOS = SRCPOS&gt;</span></span>
<span class="line"><span>struct MatmulTypeWithScale: public MatmulType&lt;POSITION, FORMAT, TYPE, ISTRANS&gt; {</span></span>
<span class="line"><span>    constexpr static TPosition scalePosition = SCALE_POSITION;</span></span>
<span class="line"><span>    constexpr static CubeFormat scaleFormat = SCALE_FORMAT;</span></span>
<span class="line"><span>    constexpr static bool isScaleTrans = SCALE_ISTRANS;</span></span>
<span class="line"><span>    constexpr static TPosition srcScalePos = SCALE_SRCPOS;</span></span>
<span class="line"><span>};</span></span></code></pre></div></li><li><p><strong>初始化操作。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling); // 初始化</span></span></code></pre></div></li><li><p><strong>设置左矩阵A、右矩阵B、左量化系数矩阵scaleA、右量化系数矩阵scaleB、Bias。</strong></p><p>通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetTensorScaleA.md" target="_blank" rel="noreferrer">SetTensorScaleA</a>、<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetTensorScaleB.md" target="_blank" rel="noreferrer">SetTensorScaleB</a>设置左量化系数矩阵scaleA、右量化系数矩阵scaleB。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mm.SetTensorA(gm_a, isTransposeA);    // 设置左矩阵A</span></span>
<span class="line"><span>mm.SetTensorB(gm_b, isTransposeB);    // 设置右矩阵B</span></span>
<span class="line"><span>mm.SetTensorScaleA(gm_scaleA, isTransposeScaleA);    // 设置左量化系数矩阵scaleA</span></span>
<span class="line"><span>mm.SetTensorScaleB(gm_scaleB, isTransposeScaleB);    // 设置右量化系数矩阵scaleB</span></span>
<span class="line"><span>mm.SetBias(gm_bias);    // 设置Bias</span></span></code></pre></div></li><li><p><strong>完成矩阵乘操作。</strong></p><ul><li><p>调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Iterate.md" target="_blank" rel="noreferrer">Iterate</a>完成单次迭代计算，叠加while循环完成单核全量数据的计算。Iterate方式，可以自行控制迭代次数，完成所需数据量的计算，方式比较灵活。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>while (mm.Iterate()) {   </span></span>
<span class="line"><span>    mm.GetTensorC(gm_c); </span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/IterateAll.md" target="_blank" rel="noreferrer">IterateAll</a>完成单核上所有数据的计算。<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/IterateAll.md" target="_blank" rel="noreferrer">IterateAll</a>方式，无需循环迭代，使用比较简单。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mm.IterateAll(gm_c);</span></span></code></pre></div></li></ul></li><li><p><strong>结束矩阵乘操作。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mm.End();</span></span></code></pre></div></li></ol><p>更多完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_mx" target="_blank" rel="noreferrer">MxMatmul样例</a>、<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_mx_ub_tscm_nz" target="_blank" rel="noreferrer">自定义输入来源的MxMatmul样例</a>、<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_mx_scale_cache" target="_blank" rel="noreferrer">scale多倍缓存的MxMatmul样例</a>。</p><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 3</strong> MatmulTypeWithScale参数说明</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.11%&quot;&gt;&lt;p&gt;参数&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.89%&quot;&gt;&lt;p&gt;说明&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.11%&quot;&gt;&lt;p&gt;POSITION&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.89%&quot;&gt;&lt;p&gt;左右矩阵的内存逻辑位置。&lt;/p&gt; &lt;p&gt;针对&lt;span&gt;Ascend 950PR/Ascend 950DT&lt;/span&gt;：&lt;/p&gt; &lt;p&gt;A矩阵可设置为TPosition::GM，TPosition::VECOUT，TPosition::TSCM&lt;/p&gt; &lt;p&gt;B矩阵可设置为TPosition::GM，TPosition::VECOUT，TPosition::TSCM&lt;/p&gt; &lt;p&gt;注意：A、B矩阵设置为TPosition::TSCM时，对应的Format仅支持CubeFormat::NZ。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.11%&quot;&gt;&lt;p&gt;SCALE_POSITION&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.89%&quot;&gt;&lt;p&gt;量化系数矩阵的内存逻辑位置。&lt;/p&gt; &lt;p&gt;针对&lt;span&gt;Ascend 950PR/Ascend 950DT&lt;/span&gt;：&lt;/p&gt; &lt;p&gt;scaleA矩阵可设置为TPosition::GM，TPosition::VECOUT，TPosition::TSCM&lt;/p&gt; &lt;p&gt;scaleB矩阵可设置为TPosition::GM，TPosition::VECOUT，TPosition::TSCM&lt;/p&gt; &lt;p&gt;注意：scaleA、scaleB矩阵设置为TPosition::TSCM时，对应的SCALE_FORMAT参数仅支持CubeFormat::NZ。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.11%&quot;&gt;&lt;p&gt;FORMAT&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.89%&quot;&gt;&lt;p&gt;数据的物理排布格式。&lt;/p&gt; &lt;p&gt;针对&lt;span&gt;Ascend 950PR/Ascend 950DT&lt;/span&gt;：&lt;/p&gt; &lt;p&gt;A矩阵可设置为CubeFormat::ND，CubeFormat::NZ，CubeFormat::VECTOR&lt;/p&gt; &lt;p&gt;B矩阵可设置为CubeFormat::ND，CubeFormat::NZ&lt;/p&gt; &lt;p&gt;注意：NZ排布格式，A/B的排布格式请参考&lt;a href=&quot;../基础知识.md#zh-cn_topic_0000001622194138_section1453415011&quot;&gt;数据格式。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.11%&quot;&gt;&lt;p&gt;TYPE&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.89%&quot;&gt;&lt;p&gt;数据类型。&lt;/p&gt; &lt;p&gt;针对&lt;span&gt;Ascend 950PR/Ascend 950DT&lt;/span&gt;：&lt;/p&gt; &lt;p&gt;A矩阵可设置为fp4x2_e1m2_t、fp4x2_e2m1_t、fp8_e4m3fn_t、fp8_e5m2_t&lt;/p&gt; &lt;p&gt;B矩阵可设置为fp4x2_e1m2_t、fp4x2_e2m1_t、fp8_e4m3fn_t、fp8_e5m2_t&lt;/p&gt; &lt;p&gt;&lt;strong&gt;注意：具体数据类型组合关系请参考&lt;/strong&gt;&lt;a href=&quot;#zh-cn_topic_0000002270097206_table5383144710452&quot;&gt;MxMatmul支持数据类型。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.11%&quot;&gt;&lt;p&gt;ISTRANS&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.89%&quot;&gt;&lt;p&gt;是否开启使能A、B矩阵转置的功能。默认值为false。参数支持的取值如下：&lt;/p&gt; &lt;p&gt;true：开启使能矩阵转置的功能，开启后，分别通过SetTensorA和SetTensorB中的isTransposeA、isTransposeB参数设置A、B矩阵是否转置。若设置A、B矩阵转置，Matmul会认为A矩阵形状为[K, M]，B矩阵形状为[N, K]。&lt;/p&gt; &lt;p&gt;false：不开启使能矩阵转置的功能，通过SetTensorA和SetTensorB不能设置A、B矩阵的转置情况。Matmul会认为A矩阵形状为[M, K]，B矩阵形状为[K, N]。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.11%&quot;&gt;&lt;p&gt;SRCPOS&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.89%&quot;&gt;&lt;p&gt;A/B矩阵的POSITION参数配置为TPosition::TSCM时，要设置TSCM中矩阵数据的来源的内存逻辑位置，默认为TPosition::GM。&lt;/p&gt; &lt;p&gt;针对&lt;span&gt;Ascend 950PR/Ascend 950DT&lt;/span&gt;：&lt;/p&gt; &lt;p&gt;A矩阵可设置为TPosition::GM，TPosition::VECOUT&lt;/p&gt; &lt;p&gt;B矩阵可设置为TPosition::GM，TPosition::VECOUT&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.11%&quot;&gt;&lt;p&gt;SCALE_FORMAT&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.89%&quot;&gt;&lt;p&gt;量化系数矩阵的物理排布格式，详细介绍请参考&lt;a href=&quot;#zh-cn_topic_0000002270097206_fig107863142019&quot;&gt;数据格式。默认值为FORMAT参数的取值。&lt;/p&gt; &lt;p&gt;针对&lt;span&gt;Ascend 950PR/Ascend 950DT&lt;/span&gt;：&lt;/p&gt; &lt;p&gt;scaleA矩阵可设置为CubeFormat::ND，CubeFormat::NZ，CubeFormat::VECTOR&lt;/p&gt; &lt;p&gt;scaleB矩阵可设置为CubeFormat::ND，CubeFormat::NZ&lt;/p&gt; &lt;p&gt;注意：&lt;/p&gt; &lt;p&gt;NZ排布格式请参考&lt;a href=&quot;../../../../编程指南/概念原理和术语/神经网络和算子/数据排布格式.md#li19960204116136&quot;&gt;NZ。MxMatmul场景，scaleA、scaleB的数据类型为fp8_e8m0_t，分形大小H0=16，W0=2。&lt;/p&gt; &lt;p&gt;在Scale矩阵为ND格式的场景中，当通过SetTensorScaleA接口设置scaleA矩阵转置时，scaleA内存排布格式必须按照(K/64, M，2)排布，通过SetTensorScaleB接口设置scaleB矩阵不转置时，scaleB内存排布格式必须按照(K/64，N， 2)排布，详细介绍请参考&lt;a href=&quot;#zh-cn_topic_0000002270097206_fig76682054103416&quot;&gt;数据格式。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.11%&quot;&gt;&lt;p&gt;SCALE_ISTRANS&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.89%&quot;&gt;&lt;p&gt;是否开启使能scaleA、scaleB矩阵转置的功能。默认值为ISTRANS参数的取值。参数支持的取值如下：&lt;/p&gt; &lt;p&gt;true：开启使能矩阵转置的功能。开启后，分别通过SetTensorScaleA和SetTensorScaleB中的isTransposeScaleA、isTransposeScaleB参数设置scaleA、scaleB矩阵是否转置。在Scale矩阵为ND格式的场景中，若设置scaleA、scaleB矩阵转置，Matmul会认为scaleA矩阵形状为[Ceil(K/64), M, 2]，scaleB矩阵形状为[N, Ceil(K/64), 2]。&lt;/p&gt; &lt;p&gt;false：不开启使能矩阵转置的功能。通过SetTensorScaleA和SetTensorScaleB不能设置scaleA、scaleB矩阵的转置情况。Matmul会认为scaleA矩阵形状为[M, Ceil(K/64), 2]，scaleB矩阵形状为[Ceil(K/64), N, 2]。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.11%&quot;&gt;&lt;p&gt;SCALE_SRCPOS&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.89%&quot;&gt;&lt;p&gt;scaleA、scaleB矩阵的SCALE_POSITION参数设置为TPosition::TSCM时，需要通过本参数设置TSCM中矩阵数据来源的内存逻辑位置，默认值为SRCPOS参数的取值。&lt;/p&gt; &lt;p&gt;针对&lt;span&gt;Ascend 950PR/Ascend 950DT&lt;/span&gt;：&lt;/p&gt; &lt;p&gt;scaleA矩阵可设置为TPosition::GM，TPosition::VECOUT&lt;/p&gt; &lt;p&gt;scaleB矩阵可设置为TPosition::GM，TPosition::VECOUT&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>MxMatmul场景仅支持<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulConfig.md" target="_blank" rel="noreferrer">Norm模板</a>和<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulConfig.md" target="_blank" rel="noreferrer">MDL模板</a>。</p></li><li><p>在MxMatmul场景中，如果A与B矩阵的位置同时为GM，对singleKIn没有特殊限制，在这种情况下，若scaleA和scaleB的K方向大小（即Ceil(singleKIn, 32)）为奇数，用户需自行在scaleA和scaleB的K方向补0至偶数。例如，当singleKIn为30时，Ceil(singleKIn, 32)为1，用户需要自行在scaleA和scaleB的K方向补0，使K方向为偶数。对于其它A、B矩阵逻辑位置的组合情况，即A与B矩阵的位置不同时为GM，singleKIn以32个元素向上对齐后的数值必须是32的偶数倍。</p></li><li><p>在MxMatmul场景中，当输入数据类型为fp4x2_e2m1_t/fp4x2_e1m2_t时，内轴必须为偶数。</p></li><li><p>在MxMatmul场景中，通过将A矩阵和scaleA矩阵的数据格式设置为VECTOR，来开启<a href="./矩阵向量乘.html">GEMV模式</a>。在此模式下，A和scaleA矩阵仅支持内存逻辑位置为GM，并且均不支持转置。</p></li><li><p>A矩阵、B矩阵为UB输入时，矩阵的内轴需要向上32字节对齐，例如，A矩阵的形状为(M, K)时，将K对齐到32字节；A矩阵的形状为(K, M)时，将M对齐到32字节。</p></li><li><p>scaleA矩阵、scaleB矩阵为UB输入时，矩阵的内轴需要向上32字节对齐，例如，scaleA矩阵的形状为(M, K/32)时，将K/32对齐到32字节；scaleA矩阵的形状为(K/32, M)时，将M对齐到32字节。</p></li><li><p>当scaleA和scaleB矩阵以ND格式输入时，高阶API在内部实现格式转换时，需要占用UB临时空间。开发者需使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetLocalWorkspace.md" target="_blank" rel="noreferrer">SetLocalWorkspace</a>接口配置临时空间，临时空间大小（单位字节）的计算公式如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int32_t scaleATmpBuf = 0;</span></span>
<span class="line"><span>int32_t scaleBTmpBuf = 0;</span></span>
<span class="line"><span>if constexpr (A_TYPE::scalePosition == TPosition::VECOUT) {</span></span>
<span class="line"><span>    if (A_TYPE::isScaleTrans) {</span></span>
<span class="line"><span>        scaleATmpBuf = CeilAlign(SingleCoreM, 32) * scaleK;</span></span>
<span class="line"><span>    } else {</span></span>
<span class="line"><span>        scaleATmpBuf = CeilAlign(scaleK, 32) * SingleCoreM;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>if constexpr (B_TYPE::scalePosition == TPosition::VECOUT) {</span></span>
<span class="line"><span>    if (B_TYPE::isScaleTrans) {</span></span>
<span class="line"><span>        scaleBTmpBuf = SingleCoreN * CeilAlign(scaleK, 32);</span></span>
<span class="line"><span>    } else {</span></span>
<span class="line"><span>        scaleBTmpBuf = scaleK * CeilAlign(SingleCoreN, 32);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int32_t totalTmpBuf = scaleATmpBuf + scaleBTmpBuf;</span></span></code></pre></div></li></ul>`,36)])])}const _=l(c,[["render",r]]);export{T as __pageData,_ as default};
